const load=(key,fallback)=>{try{let v=localStorage.getItem(key);return v?JSON.parse(v):fallback}catch{return fallback}};

const sameEmail=(a,b)=>Boolean(a&&b)&&String(a).toLowerCase()===String(b).toLowerCase();
const ownsResearch=(p,s)=>Boolean(p&&s)&&(sameEmail(p.ownerEmail,s.email)||(!p.ownerEmail&&String(p.lead||'').toLowerCase()===String(s.name||'').replace(/^Dr\.\s*/,'').toLowerCase())||(p.authors||[]).some(a=>sameEmail(a.email,s.email)&&a.role==='Lead Author'));
const isStudentResearchForFaculty=(p,s)=>Boolean(p&&s)&&(sameEmail(p.advisorEmail,s.email)||((p.advisors||[]).some(a=>sameEmail(a.email,s.email))))&& !ownsResearch(p,s);
const assignedReviewsFor=(reviews,s)=>reviews.filter(r=>s?.role==='faculty'&&(sameEmail(r.reviewerEmail,s.email)||(!r.reviewerEmail&&s?.demo)));
const defaultDraft=()=>({title:'',abstract:'',type:'',category:'',department:'Computer Engineering',keywords:'',objectives:'',authors:[],files:[],sections:{},advisorEmail:''});
function Avatar({name='',src='',className=''}){return <span className={'avatar '+className}>{src?<img src={src} alt={name+' profile photo'} className="avatar-photo"/>:String(name).charAt(0).toUpperCase()}</span>}

