function Login({setSession}){
 const go=useNavigate();
 const params=new URLSearchParams(useLocation().search);
 const initialDemo=normalizeRole(params.get('demo')||params.get('role')||'student');
 const [demoRole,setDemoRole]=useState(ROLE_LABELS[initialDemo]?initialDemo:'student');
 const [demoExpanded,setDemoExpanded]=useState(params.has('demo')||params.has('role'));
 const [email,setEmail]=useState('');
 const [password,setPassword]=useState(''),[currentPassword,setCurrentPassword]=useState('');
 const [show,setShow]=useState(false);
 const [error,setError]=useState('');
 const [signingIn,setSigningIn]=useState(false);
 function openDemo(role){if(!IS_DEMO)return;
  const profile=DEMO_PROFILES[role];
  if(!profile)return;
  // This mode never validates a password and is explicitly labelled as a demo.
  setSession({...profile,role,demo:true,avatarUrl:load('knowva.v3.avatars',{})[profile.email]||null});
  go('/app/dashboard');
 }
 async function signIn(e){
  e.preventDefault();setError('');
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())){
   setError('Enter the email address associated with your KnowVa account.');return;
  }
  if(!password){setError('Enter your password to continue.');return;}
  setSigningIn(true);
  try{
   // BACKEND CONTRACT: POST /api/auth/login -> {user:{id,name,email,role}}.
   // Server must verify password, look up the role from the database, set a secure HttpOnly session cookie,
   // and enforce role permissions on every protected API request. No role is sent from this form.
   const data=await apiRequest('/auth/login',{method:'POST',body:{email,password}});
   if(!data.user||!['student','faculty','admin'].includes(data.user.role))throw new Error('Account role is missing or unsupported. Contact the system administrator.');
   setSession({...data.user,demo:false});
   go('/app/dashboard');
  }catch(err){
   setError(err.message==='SERVER_UNAVAILABLE'||err instanceof TypeError?(IS_DEMO?'Secure university sign-in is not connected yet. Use Explore KnowVa Demo below.':'KnowVa authentication is unavailable. Please contact the system administrator.'):err.message);
  }finally{setSigningIn(false);}
 }
 return<div className="auth-page"><div className="auth-heading"><Logo dark/><p>Research Publication Management Platform</p></div>
 <form className="auth-panel" onSubmit={signIn}>
 <h2>Sign In</h2><p>Access your academic account</p>
 <label htmlFor="login-email">Account Email</label><div className="input-icon"><Mail size={16}/><input id="login-email" type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} placeholder="Email registered to your account"/></div>
 <div className="label-row"><label htmlFor="login-password">Password</label><button type="button" onClick={()=>setError('Password recovery will be available after university authentication is connected.')}>Forgot password?</button></div>
 <div className="input-icon"><Lock size={16}/><input id="login-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••" type={show?'text':'password'} autoComplete="current-password"/><button type="button" onClick={()=>setShow(!show)} aria-label={show?'Hide password':'Show password'}>{show?<Eye size={16}/>:<EyeOff size={16}/>}</button></div>
 <label className="check-label"><input type="checkbox" defaultChecked/> Remember me on this device</label>
 {error&&<div className="form-error" role="alert">{error}</div>}
 <Button className="wide" type="submit" disabled={signingIn}>{signingIn?"Signing in…":"Sign In"} <ArrowRight size={16}/></Button>
 <div className="auth-foot">Don't have an account?<button type="button" onClick={()=>go('/signup')}>Create an account</button></div>
 </form>
 {IS_DEMO&&<section className="demo-login" aria-label="Frontend demo portal access">
 <button type="button" className="demo-login-toggle" aria-expanded={demoExpanded} onClick={()=>setDemoExpanded(v=>!v)}>
 <span><span className="demo-sparkle"><Eye size={17}/></span><span><strong>Explore KnowVa Demo</strong><small>No database connected yet · Preview all three dashboards</small></span></span><ChevronDown size={17} className={demoExpanded?'turned':''}/>
 </button>
 {demoExpanded&&<div className="demo-login-body"><div className="demo-login-explain">Choose a demo workspace. This is separate from the normal login and will be removed when real authentication is integrated.</div><div className="demo-role-grid">{[['student','Student',GraduationCap],['faculty','Faculty',Building2],['admin','Admin',ShieldCheck]].map(([role,label,Icon])=><button type="button" className={'demo-role-card '+(demoRole===role?'selected':'')} onClick={()=>setDemoRole(role)} key={role}><span className="demo-role-icon"><Icon size={21}/></span><strong>{label}</strong>{demoRole===role&&<CheckCircle size={15} className="selected-check"/>}</button>)}</div><Button className="wide" onClick={()=>openDemo(demoRole)}>Launch {ROLE_LABELS[demoRole]} Demo <ArrowRight size={16}/></Button></div>}
 </section>}
 <div className="secure-small"><Lock size={13}/> {IS_DEMO?'FRONTEND DEMO · NO REAL AUTHENTICATION':'SECURED ACCESS · UNIVERSITY ACCOUNTS ONLY'}</div>
 </div>
}

function VerifyEmail(){const token=new URLSearchParams(useLocation().search).get('token')||'';const[status,setStatus]=useState('Checking verification link…');useEffect(()=>{let live=true;if(!token){setStatus('The verification link is missing its token.');return}apiRequest('/auth/verify-email?token='+encodeURIComponent(token)).then(v=>{if(live)setStatus(v.message||'Account verified. You can sign in.')}).catch(e=>{if(live)setStatus(e.message)});return()=>{live=false}},[token]);return<div className="auth-page"><div className="auth-heading"><Logo dark/><p>KnowVa Account Verification</p></div><div className="auth-panel"><h2>Verify institutional email</h2><p>{status}</p><Link to="/login">Go to Sign In</Link></div></div>}

function Signup({setSession,users,setUsers}){let go=useNavigate();let[role,setRole]=useState('student'),[name,setName]=useState(''),[email,setEmail]=useState(''),[id,setId]=useState(''),[password,setPassword]=useState(''),[confirm,setConfirm]=useState(''),[err,setErr]=useState('');async function submit(e){e.preventDefault();if(role==='student'&&!/^\d{4}-\d{5}-[A-Z]{2}-\d$/i.test(id.trim()))return setErr('Use the complete PUP student number, e.g. 2025-01673-MN-0.');if(!/^[^\s@]+@iskolarngbayan\.pup\.edu\.ph$/i.test(email))return setErr('Only @iskolarngbayan.pup.edu.ph email addresses are accepted.');if(password.length<10||!/[A-Z]/.test(password)||!/[a-z]/.test(password)||!/\d/.test(password))return setErr('Use at least 10 characters with uppercase, lowercase, and a number.');if(password!==confirm)return setErr('Passwords do not match.');if(users.some(u=>u.email.toLowerCase()===email.toLowerCase()))return setErr('This email is already registered in the demo.');if(!IS_DEMO){try{await apiRequest('/auth/register',{method:'POST',body:{name,email,universityId:id,role,password}});setErr('Registration submitted. Check your institutional email for a verification link, then sign in.');return}catch(e){setErr('Registration failed: '+e.message);return}}setUsers(u=>[...u,{name,email,id,department:'Computer Engineering',role,active:true}]);setSession({name,email,role,demo:true});go('/app/dashboard')};return<div className="auth-page signup-page"><div className="auth-heading"><Logo dark/><p>Research Publication Management Platform</p></div><form className="auth-panel" onSubmit={submit}><h2>Create an account</h2><p>Student and faculty account preview. Administrators are created by authorized staff.</p><label>Register as</label><div className="role-select">{[['student','Student',GraduationCap],['faculty','Faculty',Building2]].map(([v,label,Icon])=><button type="button" className={role===v?'selected':''} key={v} onClick={()=>setRole(v)}><Icon size={18}/>{label}</button>)}</div><label>Full Name *</label><input required value={name} onChange={e=>setName(e.target.value)} placeholder="Full name"/><label>{role==='student'?'Student ID':'Faculty ID'} *</label><input required value={id} onChange={e=>setId(e.target.value)} placeholder={role==='student'?'2025-01673-MN-0':'Faculty ID'} pattern={role==='student'?'[0-9]{4}-[0-9]{5}-[A-Za-z]{2}-[0-9]':undefined} title={role==='student'?'Format: YYYY-12345-MN-0':undefined}/><label>PUP Webmail *</label><input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@iskolarngbayan.pup.edu.ph"/><label>Password *</label><input required type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="10+ characters, upper/lowercase and a number"/><label>Confirm Password *</label><input required type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="Confirm password"/>{err&&<div className="form-error">{err}</div>}<div className="signup-disclaimer"><Info size={14}/>{IS_DEMO?'Demo registration stores your profile locally. Your password is not saved or authenticated.':'Registration will be reviewed by the backend. A verification email is required before sign-in.'}</div><Button type="submit" className="wide">{IS_DEMO?'Create Demo Account':'Request Registration'}</Button><div className="auth-foot">Already registered?<button type="button" onClick={()=>go('/login')}>Sign in</button></div></form></div>}
