function getReadiness(p){let sections=p.sections||{};let check=[
 {label:'Research title',detail:'A descriptive research title is present.',ok:!!p.title?.trim()},
 {label:'Abstract',detail:'A written abstract is provided.',ok:!!p.abstract?.trim()},
 {label:'Research keywords',detail:'Keywords help catalog and index the submission.',ok:!!p.keywords?.trim()},
 {label:'Research authors',detail:'At least one contributor is identified.',ok:(p.authors||[]).length>0},
 {label:'Manuscript content',detail:'At least an introduction or methodology is written.',ok:!!(sections.Introduction?.trim()||sections.Methodology?.trim())},
 {label:'Supporting documents',detail:'Concept paper or supporting file metadata is attached.',ok:(p.files||[]).length>0}
 ];return{checks:check,ready:check.every(x=>x.ok),completed:check.filter(x=>x.ok).length,total:check.length};}
function ValidationReadiness({project,draftMode=false}){let r=getReadiness(project);return<div className="readiness-content"><div className="readiness-summary"><div className="readiness-dial"><b>{r.completed}/{r.total}</b><small>ready</small></div><div><h3>{r.ready?'Document preflight complete':'Document preflight checklist'}</h3><p>{draftMode?'You can prepare your draft now. Formal validation occurs later in the approved journal workflow.':'This is a client-side completeness check based on the information entered. It cannot identify AI-generated text or search for copied sources.'}</p></div></div><div className="readiness-list">{r.checks.map(c=><div className="readiness-item" key={c.label}><span className={c.ok?'check-ok':'check-wait'}>{c.ok?<Check size={16}/>:<Clock size={16}/>}</span><div><strong>{c.label}</strong><small>{c.detail}</small></div><span className={c.ok?'ready-state':'pending-state'}>{c.ok?'READY':'MISSING'}</span></div>)}</div><div className="validator-disclaimer"><AlertTriangle size={18}/><div><strong>The readiness checklist is separate from manuscript comparison.</strong><p>This panel checks form completeness only. It does not produce an AI probability, plagiarism percentage, or academic integrity decision. Use the Internal Text Comparison above for repository-only overlap; all findings still require human review.</p></div></div></div>}
function Modal({title,children,onClose}){useEffect(()=>{function fn(e){if(e.key==='Escape')onClose()}document.addEventListener('keydown',fn);return()=>document.removeEventListener('keydown',fn)},[onClose]);return<div className="modal-backdrop" onMouseDown={onClose}><div className="modal-card" onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><h2>{title}</h2><button className="tiny-icon" onClick={onClose}><X size={20}/></button></div><div className="modal-content">{children}</div></div></div>}
function downloadCSV(data,name){if(!data.length)return;let keys=[...new Set(data.flatMap(x=>Object.keys(x)))];let csv=[keys.join(','),...data.map(x=>keys.map(k=>{let v=typeof x[k]==='object'?JSON.stringify(x[k]):String(x[k]??'');return '"'+v.replaceAll('"','""')+'"'}).join(','))].join('\r\n');downloadBlob(csv,name,'text/csv;charset=utf-8')};function downloadJSON(data,name){downloadBlob(JSON.stringify(data,null,2),name,'application/json')};function downloadBlob(content,name,type){let url=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
export default App;
